-- 177 | 2026-11-22 | Sourced VPP top-up for Xuân Hòa + Bàn Cờ (old HCMC).
-- 5 real map-listed points, not registered-only offices; Cầu Ông Lãnh under separate review.
-- Sales must confirm operating status, GPS and field visits. No fake coordinates, visits or customer conversion.
-- Phone left NULL when conflicting/unverified. One lead at 136 Nguyễn Đình Chiểu despite alternate Lộc business names.
-- Source batch is idempotent and rejects collisions by key, Google Place ID, phone, name, address and customer matches.
WITH vetted AS (SELECT * FROM jsonb_to_recordset('[{"ward":"Xuân Hòa","district":"Quận 3","name":"Crabit Studio Sài Gòn","street":"270D Võ Thị Sáu","oldward":"Võ Thị Sáu","phone":"0879203702","place":"ChIJx7QbgQQvdTERAbunVGVp93Y","source":"https://www.crabit.vn/he-thong-cua-hang-crabit-studio","proof":"Hệ thống cửa hàng trên website Crabit xác nhận cửa hàng Sài Gòn ở 270D Võ Thị Sáu, có sổ tay và văn phòng phẩm; Maps có hồ sơ riêng, địa chỉ mới Xuân Hòa.","address_new":"270D Võ Thị Sáu, phường Xuân Hòa, TP. Hồ Chí Minh","address_old":"270D Võ Thị Sáu, Võ Thị Sáu cũ, Quận 3, TP.HCM cũ","category":"van_phong_pham","key":"gmaps:ChIJx7QbgQQvdTERAbunVGVp93Y","maps":"https://www.google.com/maps/search/?api=1&query=Crabit%20Studio%20S%C3%A0i%20G%C3%B2n%20270D%20V%C3%B5%20Th%E1%BB%8B%20S%C3%A1u%20H%E1%BB%93%20Ch%C3%AD%20Minh&query_place_id=ChIJx7QbgQQvdTERAbunVGVp93Y"},{"ward":"Xuân Hòa","district":"Quận 3","name":"Lộc Art Store - Nguyễn Đình Chiểu","street":"136 Nguyễn Đình Chiểu","oldward":"Phường 6","phone":null,"place":"ChIJzfR9VwAvdTERogw9835gIV8","source":"https://toplist.vn/top-list/dia-chi-ban-hoa-cu-chat-luong-gia-tot-tai-tphcm-53797.htm","proof":"Danh sách họa cụ nêu cửa hàng bán lẻ tại 136 Nguyễn Đình Chiểu, phường 6 cũ; Maps ghi Lộc Art Store, phường Xuân Hòa. Cùng mặt bằng với tên Họa phẩm Lộc/Nhà sách Lộc, chỉ ghi một lead.","address_new":"136 Nguyễn Đình Chiểu, phường Xuân Hòa, TP. Hồ Chí Minh","address_old":"136 Nguyễn Đình Chiểu, Phường 6 cũ, Quận 3, TP.HCM cũ","category":"van_phong_pham","key":"gmaps:ChIJzfR9VwAvdTERogw9835gIV8","maps":"https://www.google.com/maps/search/?api=1&query=L%E1%BB%99c%20Art%20Store%20-%20Nguy%E1%BB%85n%20%C4%90%C3%ACnh%20Chi%E1%BB%83u%20136%20Nguy%E1%BB%85n%20%C4%90%C3%ACnh%20Chi%E1%BB%83u%20H%E1%BB%93%20Ch%C3%AD%20Minh&query_place_id=ChIJzfR9VwAvdTERogw9835gIV8"},{"ward":"Bàn Cờ","district":"Quận 3","name":"B.Corner - Nguyễn Đình Chiểu","street":"419 Nguyễn Đình Chiểu","oldward":"Phường 5","phone":null,"place":"ChIJBbxoLSIvdTERQPp1ZU6JYWQ","source":"https://www.bigbuy360.vn/members/bcorner93","proof":"Mô tả gian hàng B.Corner chỉ rõ chi nhánh bán trực tiếp 419 Nguyễn Đình Chiểu; chuyên sổ tay, bút, đồ học tập và quà. Maps ghi phường Bàn Cờ. Số điện thoại giữa các nguồn chưa thống nhất nên để trống.","address_new":"419 Nguyễn Đình Chiểu, phường Bàn Cờ, TP. Hồ Chí Minh","address_old":"419 Nguyễn Đình Chiểu, Phường 5 cũ, Quận 3, TP.HCM cũ","category":"van_phong_pham","key":"gmaps:ChIJBbxoLSIvdTERQPp1ZU6JYWQ","maps":"https://www.google.com/maps/search/?api=1&query=B.Corner%20-%20Nguy%E1%BB%85n%20%C4%90%C3%ACnh%20Chi%E1%BB%83u%20419%20Nguy%E1%BB%85n%20%C4%90%C3%ACnh%20Chi%E1%BB%83u%20H%E1%BB%93%20Ch%C3%AD%20Minh&query_place_id=ChIJBbxoLSIvdTERQPp1ZU6JYWQ"},{"ward":"Bàn Cờ","district":"Quận 3","name":"Gia Đình Gấu Washi - Cư xá Đô Thành","street":"6 Đường số 2, Cư xá Đô Thành","oldward":"Phường 4","phone":null,"place":"ChIJgUnSUEsvdTERDUGnhyWSMUo","source":"https://nhasachhoasen.com/khang-nuoc-con-but-ve-liner-zig-nsh9834184884.html","proof":"Người bán Washi Gia Đình Gấu 1905 công khai mua trực tiếp tại số 6 Đường số 2, cư xá Đô Thành; có bút/sổ/họa cụ. Maps ghi Bàn Cờ. Cần Sales xác minh quầy bán, có thể là điểm bán kết hợp trực tuyến.","address_new":"6 Đường số 2, Cư xá Đô Thành, phường Bàn Cờ, TP. Hồ Chí Minh","address_old":"6 Đường số 2, Cư xá Đô Thành, Phường 4 cũ, Quận 3, TP.HCM cũ","category":"van_phong_pham","key":"gmaps:ChIJgUnSUEsvdTERDUGnhyWSMUo","maps":"https://www.google.com/maps/search/?api=1&query=Gia%20%C4%90%C3%ACnh%20G%E1%BA%A5u%20Washi%20-%20C%C6%B0%20x%C3%A1%20%C4%90%C3%B4%20Th%C3%A0nh%206%20%C4%90%C6%B0%E1%BB%9Dng%20s%E1%BB%91%202%2C%20C%C6%B0%20x%C3%A1%20%C4%90%C3%B4%20Th%C3%A0nh%20H%E1%BB%93%20Ch%C3%AD%20Minh&query_place_id=ChIJgUnSUEsvdTERDUGnhyWSMUo"},{"ward":"Bàn Cờ","district":"Quận 3","name":"Văn phòng phẩm và đồ chơi Phương Uyên","street":"186 Nguyễn Thượng Hiền","oldward":"Quận 3 cũ (chưa xác nhận phường số)","phone":"0904409074","place":"ChIJuYlhdiQvdTER2uYyJZ2J90A","source":"https://www.google.com/maps/search/?api=1&query=Van%20phong%20pham%20Phuong%20Uyen%20186%20Nguyen%20Thuong%20Hien%20TPHCM&query_place_id=ChIJuYlhdiQvdTER2uYyJZ2J90A","proof":"Google Maps có listing riêng tại số 186 Nguyễn Thượng Hiền, phường Bàn Cờ, danh mục stationery store, điện thoại và ít đánh giá. Chưa có nguồn hãng hoặc bằng chứng ghé quầy nên cần khảo sát xác nhận.","address_new":"186 Nguyễn Thượng Hiền, phường Bàn Cờ, TP. Hồ Chí Minh","address_old":"186 Nguyễn Thượng Hiền, Quận 3 cũ (chưa xác nhận phường số) cũ, Quận 3, TP.HCM cũ","category":"van_phong_pham","key":"gmaps:ChIJuYlhdiQvdTER2uYyJZ2J90A","maps":"https://www.google.com/maps/search/?api=1&query=V%C4%83n%20ph%C3%B2ng%20ph%E1%BA%A9m%20v%C3%A0%20%C4%91%E1%BB%93%20ch%C6%A1i%20Ph%C6%B0%C6%A1ng%20Uy%C3%AAn%20186%20Nguy%E1%BB%85n%20Th%C6%B0%E1%BB%A3ng%20Hi%E1%BB%81n%20H%E1%BB%93%20Ch%C3%AD%20Minh&query_place_id=ChIJuYlhdiQvdTER2uYyJZ2J90A"}]'::jsonb) AS s(ward text,district text,name text,street text,oldward text,phone text,place text,source text,proof text,address_new text,address_old text,category text,key text,maps text) WHERE
  s.ward IN ('Xuân Hòa','Bàn Cờ','Cầu Ông Lãnh')
  AND s.category='van_phong_pham'
  AND s.source LIKE 'https://%'
  AND s.address_new LIKE '%phường '||s.ward||'%'
  AND (s.phone IS NULL OR s.phone ~ '^[0-9]{8,11}$')
  AND s.place ~ '^ChIJ[A-Za-z0-9_-]{20,}$'
  AND EXISTS (SELECT 1 FROM public.sales_hcm_old_wards w WHERE w.province='TP Hồ Chí Minh' AND w.ward_new=s.ward AND w.legacy_district=s.district AND w.active)
  AND NOT EXISTS (SELECT 1 FROM public.field_prospects p WHERE p.research_source_key=s.key OR p.google_place_id=s.place
      OR lower(btrim(p.address_line))=lower(btrim(s.address_new))
      OR (p.province='TP Hồ Chí Minh' AND p.ward_new=s.ward AND lower(btrim(p.name))=lower(btrim(s.name)))
      OR (s.phone IS NOT NULL AND regexp_replace(coalesce(p.phone,''),'[^0-9]','','g')=s.phone))
  AND NOT EXISTS (SELECT 1 FROM public.customers c WHERE lower(btrim(c.address_line))=lower(btrim(s.address_new))
      OR (c.province='TP Hồ Chí Minh' AND lower(btrim(c.name))=lower(btrim(s.name)))
      OR (s.phone IS NOT NULL AND regexp_replace(coalesce(c.phone,''),'[^0-9]','','g')=s.phone))), inserted AS (
 INSERT INTO public.field_prospects (
   id,area_visit_id,owner_sub,name,address_line,province,district,ward_new,address_legacy,
   category,phone,tax_code,note,status,source_kind,research_source_key,research_source_url,
   research_batch,google_maps_url,google_place_id)
 SELECT gen_random_uuid(),NULL,'ef943de4-18f7-49ef-8340-eefb18855534',s.name,s.address_new,
   'TP Hồ Chí Minh',s.district,s.ward,s.address_old,s.category,s.phone,NULL,
   'Nguồn tra cứu 22/11/2026; CHƯA GHÉ / CHƯA XÁC MINH GPS và hoạt động cửa hàng. '||s.proof||' Nguồn: '||s.source,
   'new','manual',s.key,s.source,'2026-11-22-hcm-old-vpp-xuan-hoa-ban-co-177',s.maps,s.place
 FROM vetted s
 ON CONFLICT (research_source_key) WHERE research_source_key IS NOT NULL DO NOTHING
 RETURNING ward_new,name,category,phone,google_place_id)
SELECT ward_new,name,category,phone,google_place_id FROM inserted ORDER BY ward_new,name;
